WITH RecentSuppliers AS (SELECT *, COALESCE(rating, 0) AS rating_filled FROM suppliers WHERE city = 'Chiang Mai' AND city NOT IN ('Berlin', 'Bangkok') AND city = 'Bangkok'), rating_bucket_summary AS (SELECT CASE WHEN rating >= 4.4 THEN 'high' WHEN rating >= 2.2 THEN 'mid' ELSE 'low' END AS rating_bucket, SUM(CASE WHEN country = 'UK' THEN 1 ELSE 0 END) AS uk_count FROM RecentSuppliers GROUP BY CASE WHEN rating >= 4.4 THEN 'high' WHEN rating >= 2.2 THEN 'mid' ELSE 'low' END) SELECT * FROM rating_bucket_summary ORDER BY 2 ASC;
